      "path": "packages/dsh-tool-describe-image/cordis.patch.yml",
      "content": "# dsh-tool-describe-image bundle patch: inserts the describe_image tool plugin\n# row into the web profile roster. Applied as a profile bundle layer (the\n# `dsh.bundle.patch` manifest field); install with\n# `dsh plugin --profile web add link:<repo>/packages/dsh-tool-describe-image`.\n#\n# One package, both halves: the node half (exports \".\") runs in the host\n# process and registers the model-facing describe_image tool, the\n# /describe-image/attach upload route, and the \"Image understanding\"\n# settings section; the browser half (declared by `dsh.client`, served from\n# lib/client.js) rewrites image-bearing sends into describe-image references\n# at submit time. The settings card itself is rendered by the web GUI's\n# built-in plugin config page from the `describe-image` settings section.\n- insert:\n    - id: describe-image\n      name: '@linxin666/dsh-tool-describe-image'\n"
    },
    {
      "path": "packages/dsh-tool-describe-image/tsdown.config.ts",
      "content": "/**\n * Standalone build config for the dsh-tool-describe-image plugin.\n *\n * Uses the repo's shared client-bundle preset (shared/tsdown.client.ts):\n * the node half (tool registration + attach route + settings section +\n * HTTP client) builds to lib/, and the browser half is auto-detected at\n * src/client/index.ts and emitted as lib/client.js. Runtime\n * @deepseek-ai/* peers stay external; schemastery is a declared\n * dependency and rides the host install too.\n */\nimport { clientBundle } from '../../shared/tsdown.client.ts'\n\nexport default clientBundle('@linxin666/dsh-tool-describe-image', ['src/index.ts', 'src/invariant.ts'], {\n  libExternal: [\n    '@deepseek-ai/dsh-attachment',\n    '@deepseek-ai/dsh-credentials',\n    '@deepseek-ai/dsh-launch-environment',\n    '@deepseek-ai/dsh-settings',\n    '@deepseek-ai/dsh-tools',\n    'schemastery',\n  ],\n})\n"
    },
    {
      "path": "packages/dsh-tool-describe-image/src/config-resolve.ts",
      "content": "/**\n * Config and credential facts for the describe-image tool. Holds the validated\n * ResolvedConfig snapshot (defaults, bounds, and endpoint facts), the API-key\n * resolution seams, and the schemastery section that doubles as the plugin's\n * settings card schema. Kept separate from tool registration and the vision\n * HTTP client so single purpose stays single file.\n * @module @linxin666/dsh-tool-describe-image/config\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport z from 'schemastery'\nimport { credentialRef } from '@deepseek-ai/dsh-credentials'\nimport type { CredentialRef } from '@deepseek-ai/dsh-credentials'\nimport { launchEnvironmentOf } from '@deepseek-ai/dsh-launch-environment'\nimport { settingsNamespace } from '@deepseek-ai/dsh-settings'\nimport { DEFAULT_MAX_BYTES } from './media.ts'\n\n/** Environment-variable name the API key resolves through when no inline key is configured. */\nexport const DEFAULT_API_KEY_ENV = 'VISION_API_KEY'\n/** Per-call output-token cap sent to the vision model. */\nexport const DEFAULT_MAX_OUTPUT_TOKENS = 1024\n/** Per-call vision request timeout in milliseconds. */\nexport const DEFAULT_TIMEOUT_MS = 60_000\n/** Protocol styles the tool can speak to the configured endpoint. */\nexport const API_STYLES = ['chat-completions', 'responses'] as const\nexport type ApiStyle = typeof API_STYLES[number]\n/** Protocol style used unless the configuration overrides it. */\nexport const DEFAULT_API_STYLE: ApiStyle = 'chat-completions'\n/** Instruction sent when the model does not pass its own prompt. */\nexport const DEFAULT_PROMPT =\n  'Analyze this image: describe what is visible factually, transcribe legible text verbatim, and call out layout, notable details, or anything anomalous.'\n\n/**\n * Deployment configuration for the describe-image tool. The interface keeps every field optional so\n * programmatic construction is re-judged by {@link resolveConfig}; the schema requires `baseURL` and\n * `model` for composition entries.\n */\nexport interface Config {\n  /** Root of the OpenAI-compatible endpoint, e.g. `https://api.openai.com/v1`; trailing slashes are stripped. */\n  baseURL?: string\n  /** Vision model id for the configured endpoint. */\n  model?: string\n  /** Inline API key; prefer `apiKeyEnv` with the credential seam. Feed from the environment via `!!js process.env.VISION_API_KEY`. */\n  apiKey?: string\n  /** Credential reference (environment-variable name) for the API key; defaults to `VISION_API_KEY`. */\n  apiKeyEnv?: string\n  /** Instruction used when a call omits its `prompt`; defaults to a concise factual description. */\n  defaultPrompt?: string\n  /** Image byte bound; defaults to {@link DEFAULT_MAX_BYTES}. */\n  maxBytes?: number\n  /** Output-token cap sent to the vision model; defaults to {@link DEFAULT_MAX_OUTPUT_TOKENS}. */\n  maxOutputTokens?: number\n  /** Per-call request timeout; defaults to {@link DEFAULT_TIMEOUT_MS}. */\n  timeoutMs?: number\n  /** Protocol style of the endpoint; defaults to {@link DEFAULT_API_STYLE} (`chat-completions`). */\n  apiStyle?: ApiStyle\n}\n\n/** Schemastery configuration for the describe-image tool; doubles as the `describe-image` settings-section schema. */\nexport const Config: z<Config> = z.object({\n  baseURL: z.string(),\n  model: z.string(),\n  apiKey: z.string().role('secret'),\n  apiKeyEnv: z.string().role('credential-ref').default(DEFAULT_API_KEY_ENV),\n  defaultPrompt: z.string().default(DEFAULT_PROMPT),\n  maxBytes: z.number().step(1).min(1).default(DEFAULT_MAX_BYTES),\n  maxOutputTokens: z.number().step(1).min(1).default(DEFAULT_MAX_OUTPUT_TOKENS),\n  timeoutMs: z.number().min(1).default(DEFAULT_TIMEOUT_MS),\n  apiStyle: z.union(API_STYLES).default(DEFAULT_API_STYLE),\n})\n\n/** Settings namespace carrying the endpoint, model, and key reference the Plugins card edits. */\nexport const DESCRIBE_IMAGE_SETTINGS_NAMESPACE = settingsNamespace('describe-image')\n\n/** One resolved, validated configuration snapshot; defaults and beyond-schema constraints applied. */\nexport interface ResolvedConfig {\n  baseURL: string\n  model: string\n  apiKey: string | undefined\n  apiKeyEnv: CredentialRef | undefined\n  defaultPrompt: string\n  maxBytes: number\n  maxOutputTokens: number\n  timeoutMs: number\n  apiStyle: ApiStyle\n}\n\n/**\n * Resolve raw config into validated connection facts. Programmatic construction may bypass\n * Schemastery normalization, so every default and bound is re-judged here; a non-empty composition\n * entry is validated at load so misconfiguration fails loud (an unconfigured family mount only\n * hits it per call, inside {@link apply}).\n * @param config - raw plugin config.\n * @returns validated facts.\n */\nexport function resolveConfig(config: Config): ResolvedConfig {\n  const baseURL = (config.baseURL ?? '').trim().replace(/\\/+$/, '')\n  if (!/^https?:\\/\\//.test(baseURL)) {\n    throw new Error('describe-image: baseURL must be an absolute http(s) URL')\n  }\n  const model = (config.model ?? '').trim()\n  if (model.length === 0) throw new Error('describe-image: model must be a non-empty model id')\n  const apiKey = config.apiKey\n  if (apiKey !== undefined && apiKey.length === 0) {\n    throw new Error('describe-image: apiKey must be non-empty when set')\n  }\n  let apiKeyEnv: CredentialRef | undefined\n  const rawEnv = config.apiKeyEnv ?? DEFAULT_API_KEY_ENV\n  if (rawEnv.length > 0) {\n    try {\n      apiKeyEnv = credentialRef(rawEnv)\n    } catch {\n      throw new Error(`describe-image: apiKeyEnv ${JSON.stringify(rawEnv)} is not a valid environment-variable name`)\n    }\n  }\n  const maxBytes = config.maxBytes ?? DEFAULT_MAX_BYTES\n  const maxOutputTokens = config.maxOutputTokens ?? DEFAULT_MAX_OUTPUT_TOKENS\n  const timeoutMs = config.timeoutMs ?? DEFAULT_TIMEOUT_MS\n  const apiStyle = config.apiStyle ?? DEFAULT_API_STYLE\n  for (const [field, value] of [['maxBytes', maxBytes], ['maxOutputTokens', maxOutputTokens], ['timeoutMs', timeoutMs]] as const) {\n    if (!Number.isSafeInteger(value) || value <= 0) {\n      throw new Error(`describe-image: ${field} must be a positive safe integer`)\n    }\n  }\n  if (!API_STYLES.includes(apiStyle)) {\n    throw new Error(`describe-image: apiStyle must be one of ${API_STYLES.map(style => JSON.stringify(style)).join(', ')}`)\n  }\n  return { baseURL, model, apiKey, apiKeyEnv, defaultPrompt: config.defaultPrompt ?? DEFAULT_PROMPT, maxBytes, maxOutputTokens, timeoutMs, apiStyle }\n}\n\n/**\n * Resolve the API key for one call: an explicit inline key wins; otherwise the credential seam (which owns\n * environment and managed-store layers) resolves the reference; without the seam the launch environment is\n * the whole credential plane.\n * @param ctx - registrant context.\n * @param spec - validated configuration.\n * @returns the resolved key.\n */\nexport async function resolveApiKey(ctx: Context, spec: ResolvedConfig): Promise<string> {\n  if (spec.apiKey !== undefined) return spec.apiKey\n  if (spec.apiKeyEnv !== undefined) {\n    const credentials = ctx.get('credentials')\n    if (credentials !== undefined) {\n      const hit = await credentials.resolve(spec.apiKeyEnv)\n      if (hit !== undefined) return hit.value\n    } else {\n      const ambient = launchEnvironmentOf(ctx).get(spec.apiKeyEnv)\n      if (ambient !== undefined && ambient.value.length > 0) return ambient.value\n    }\n  }\n  throw new Error(\n    `describe-image: no API key; set apiKey, store ${spec.apiKeyEnv ?? DEFAULT_API_KEY_ENV} through the credentials service,`\n    + ' or export it in the launching environment',\n  )\n}\n"
    },
    {
      "path": "packages/dsh-tool-describe-image/src/client/index.ts",
      "content": "/**\n * Browser half of the describe-image plugin: no composer chrome of its own.\n * The shell's input box has no image entry for text-only models, so image\n * sends are rewritten at submit time (installSendHook) into describe-image\n * references before they reach the model — the way a text-only model gets an\n * image to analyze without the shell's vision pipeline. The settings card is\n * rendered by the web GUI's built-in plugin config page from the host-side\n * `describe-image` section.\n *\n * Failure policy: every DOM/runtime wiring failure is logged, never thrown —\n * the web shell fails the whole boot when a plugin apply throws.\n * @module @linxin666/dsh-tool-describe-image/client\n */\n\nimport type { ClientContext, SettingsScope, SettingsScopeSpec } from '@deepseek-ai/dsh-client-runtime/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-slots'\nimport type {} from '@deepseek-ai/dsh-client-ui-conversation/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-settings/client'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport { installSendHook } from './send-hook.ts'\nimport { DescribeImageSettingsCard, DescribeImageSettingsCardController, type DescribeImageSettings } from './DescribeImageSettingsCard.tsx'\nimport { dictionaries, setLanguage, type DescribeImageClientKey } from './locales.ts'\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    /** The describe-image attach button copy. */\n    'describe-image': DescribeImageClientKey\n  }\n\n  interface SlotMap {\n    /**\n     * One family plugin card inside the Web UI Plugins group. Spelled here\n     * with the same shape so this package can register without depending on\n     * the sibling web-ui-settings package.\n     */\n    'web-ui.plugin.item': { kind: 'list'; scope: 'root'; owner: SettingsPluginItemOwnerProps }\n  }\n}\n\n/** Owner share of a plugin card (the section supplies nothing). */\nexport interface SettingsPluginItemOwnerProps {\n  /** Marker field: card owner props are intentionally empty. */\n  children?: never\n}\n\ndeclare module '@deepseek-ai/cordis' {\n  interface Context {\n    /**\n     * Optional rc.6 compatibility binder provided by dsh-web-ui-settings;\n     * absent when that group plugin is not installed, so callers fall back to\n     * the official settings scope.\n     */\n    webUiSettings?: { bind<S>(spec: SettingsScopeSpec<S>): SettingsScope<S> }\n  }\n}\n\n/** Locale namespace of the browser half. */\nexport const NS = 'describe-image' as const\n\n/** Required services: slots for the settings card, conversation for the send hook, settings scope and locale for the card copy. */\nexport const inject = ['slots', 'conversation', 'settingsScope', 'locale']\n\n/** Apply the browser half. */\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(NS, dictionaries), 'dsh-tool-describe-image: dictionaries')\n  ctx.effect(() => {\n    // Mirror the shell language into the module-level dictionary switch.\n    const sync = (): void => {\n      const lang = document.documentElement.lang\n      setLanguage(lang === 'zh' || lang.startsWith('zh-') ? 'zh' : 'en')\n    }\n    sync()\n    const observer = new MutationObserver(sync)\n    observer.observe(document.documentElement, { attributes: true, attributeFilter: ['lang'] })\n    return () => observer.disconnect()\n  }, 'dsh-tool-describe-image: language mirror')\n\n  ctx.inject(['slots', 'conversation'], (scope: ClientContext) => {\n    const conversation = scope.conversation\n    const slots = scope.slots\n\n    // Text-only models reject image blocks at submit: rewrite image-bearing\n    // sends into describe-image references before they reach the model.\n    installSendHook(conversation)\n\n    // The settings card: bound to the describe-image namespace through the\n    // family bridge when the official scope does not expose it.\n    ctx.inject(['settingsScope'], (settingsCtx: ClientContext) => {\n      const binder = settingsCtx.get('webUiSettings') ?? settingsCtx.settingsScope\n      const settingsScope = binder.bind<DescribeImageSettings>({ namespace: NS })\n      const settingsCard = new DescribeImageSettingsCardController(settingsScope)\n      slots.inject('web-ui.plugin.item', () =>\n        slots.register({\n          name: 'web-ui.plugin.item',\n          id: 'describe-image',\n          order: 115,\n          locale: NS,\n          inject: () => settingsCard.inject(),\n        }, DescribeImageSettingsCard))\n    })\n  })\n}\n"
    },
    {
      "path": "packages/dsh-tool-describe-image/src/client/send-hook.ts",
      "content": "/**\n * Send interception: text-only models reject image blocks at submit, so a\n * send that carries draft images is rewritten into a plain-text prompt that\n * carries describe-image references instead. The images are uploaded through\n * the host attach route (so bytes stay out of the conversation log), the\n * draft images are released, and the model analyzes them through the\n * describe_image tool rather than receiving the bytes it cannot read.\n *\n * The hook wraps the conversation service's sendSession method in place. It\n * is structural (no dependency on the conversation package's internal\n * types) and idempotent (a module marker guards against double install).\n * @module @linxin666/dsh-tool-describe-image/client/send-hook\n */\n\nimport { readFileAsBase64, uploadImageForDescribe } from './attach.ts'\n\n/** One draft image as the conversation service hands it back. */\ninterface DraftImageFace {\n  readonly id: string\n  readonly file: File\n}\n\n/** One text prompt block. */\ninterface TextBlock { type: 'text'; text: string }\n\n/** Prompt result shape returned by the session RPC. */\ninterface PromptResult { ok: boolean; error?: { code: string; message?: string } }\n\n/** The session face needed to re-send a text-only prompt. */\ninterface SessionPromptFace {\n  prompt(content: readonly TextBlock[], mode: string): Promise<PromptResult>\n}\n\n/** The conversation-service surface this hook wraps. */\ninterface ConversationSendFace {\n  send(text: string): Promise<void>\n  sendSession(session: SessionPromptFace, text: string, imageIds: readonly string[], mode: string): Promise<void>\n  draftImages(ids: readonly string[]): readonly DraftImageFace[]\n  releaseDraftImage(id: string): void\n}\n\n/** Installed-marker key on the wrapped service instance. */\nconst HOOK_MARKER = '__dshDescribeImageSendHooked'\n\n/**\n * Wrap the conversation service so image-bearing sends route through the\n * describe-image attach seam. No-op when the service surface is unavailable\n * (older shell) or already wrapped.\n * @param conversation - the `conversation` service instance.\n */\nexport function installSendHook(conversation: unknown): void {\n  const face = conversation as ConversationSendFace\n  if (face === null || typeof face !== 'object') return\n  if (typeof face.sendSession !== 'function') return\n  if (typeof face.draftImages !== 'function' || typeof face.releaseDraftImage !== 'function') return\n  if ((face as unknown as Record<string, unknown>)[HOOK_MARKER] === true) return\n\n  const original = face.sendSession\n  face.sendSession = async (session, text, imageIds, mode): Promise<void> => {\n    if (imageIds.length === 0) {\n      return original.call(face, session, text, imageIds, mode)\n    }\n    const attachments = face.draftImages(imageIds)\n    if (attachments.length !== imageIds.length) {\n      return original.call(face, session, text, imageIds, mode)\n    }\n    const refs: string[] = []\n    for (const attachment of attachments) {\n      const read = await readFileAsBase64(attachment.file)\n      if (!read.ok) break\n      const upload = await uploadImageForDescribe(read.base64, attachment.file.type, attachment.file.name)\n      if (!upload.ok) break\n      refs.push(upload.markdown)\n    }\n    if (refs.length !== attachments.length) {\n      // Upload fell short: keep the shell's original behavior (which will\n      // reject the image block for a text-only model).\n      return original.call(face, session, text, imageIds, mode)\n    }\n    const fullText = [text.trim(), ...refs].filter(part => part !== '').join('\\n')\n    const result = await session.prompt([{ type: 'text', text: fullText }], mode)\n    if (!result.ok) {\n      throw new Error(`conversation.send failed: ${result.error?.code ?? 'unknown'}: ${result.error?.message ?? ''}`)\n    }\n    for (const id of imageIds) face.releaseDraftImage(id)\n  }\n  ;(face as unknown as Record<string, unknown>)[HOOK_MARKER] = true\n}\n"
    },
    {
      "path": "packages/dsh-tool-describe-image/src/attach-routes.ts",
      "content": "/**\n * The /describe-image/attach route: a browser-to-host upload seam that turns a\n * picked image into a durable attachment reference and returns the\n * `[image attachment …]` note text the browser half splices into the composer\n * draft. The note is plain text, so a text-only model sees the reference and\n * can hand the exact JSON to describe_image; the image bytes themselves never\n * cross into the conversation log — they live in the attachment store, exactly\n * like images the vision pipeline uploads.\n *\n * The route works without any plugin configuration (the family aggregate mounts\n * this way): the byte bound falls back to the default and the attachment store\n * is resolved per call, failing with a clear message when it is absent.\n * @module @linxin666/dsh-tool-describe-image/attach\n */\n\nimport type { IncomingMessage, ServerResponse } from 'node:http'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ImageAttachmentRef } from '@deepseek-ai/dsh-attachment'\nimport { decodeBase64, isImageMimeType, sniffMimeType, DEFAULT_MAX_BYTES, type ImageMimeType } from './media.ts'\n\n/** Request-body byte cap: base64 of a {@link DEFAULT_MAX_BYTES} image plus envelope slack. */\nexport const MAX_ATTACH_BODY_BYTES = 16 * 1024 * 1024\n\n/** Stable error codes the browser half surfaces without leaking internals. */\nexport interface AttachError {\n  /** `rejected`: the image or payload fails validation; `internal`: the route or store failed. */\n  code: 'rejected' | 'internal'\n  message: string\n}\n\n/** Validated upload payload. */\nexport interface AttachPayload {\n  /** Base64-encoded image bytes (standard alphabet). */\n  data: string\n  /** Media type the sender declares; verified against magic bytes. */\n  mediaType: ImageMimeType\n  /** Optional display name; never interpreted as a path. */\n  name?: string\n}\n\n/** Outcome of one attach attempt. */\nexport type AttachOutcome =\n  | { ok: true; ref: ImageAttachmentRef; note: string; markdown: string }\n  | { ok: false; error: AttachError }\n\n/** The failure envelope used when a non-POST request hits the route. */\nexport const METHOD_NOT_ALLOWED: AttachError = { code: 'internal', message: 'only POST is allowed' }\n\n/**\n * In-memory registry of references this process's attach route persisted,\n * keyed by attachment id. Text models that copy only the id out of an\n * `[image attachment …]` note (instead of the whole JSON) still resolve\n * through here, and the attachment store's digest verification runs on the\n * read regardless. Bounded FIFO; ids are content-addressed so a stale entry\n * cannot be confused with another image.\n */\nconst ATTACHMENT_REF_REGISTRY = new Map<string, ImageAttachmentRef>()\n\n/** Registry capacity; beyond it the oldest entry is dropped. */\nconst ATTACHMENT_REF_REGISTRY_CAP = 128\n\n/** Remember one persisted reference by its attachment id. */\nexport function registerAttachmentRef(ref: ImageAttachmentRef): void {\n  ATTACHMENT_REF_REGISTRY.delete(ref.attachmentId)\n  ATTACHMENT_REF_REGISTRY.set(ref.attachmentId, ref)\n  while (ATTACHMENT_REF_REGISTRY.size > ATTACHMENT_REF_REGISTRY_CAP) {\n    const oldest = ATTACHMENT_REF_REGISTRY.keys().next().value\n    if (oldest === undefined) break\n    ATTACHMENT_REF_REGISTRY.delete(oldest)\n  }\n}\n\n/** Look up a persisted reference by its bare attachment id, if still in the registry. */\nexport function attachmentRefById(id: string): ImageAttachmentRef | undefined {\n  return ATTACHMENT_REF_REGISTRY.get(id)\n}\n\n/**\n * The markdown image reference inserted into the composer draft: short,\n * renders as an image/link in the conversation, and carries the attachment\n * id in the URL so a text model can extract it and hand it to\n * describe_image (the tool resolves bare ids through the registry).\n * @param id - the attachment id (e.g. `sha256:…`).\n * @returns the markdown text to splice into the draft.\n */\nexport function attachmentMarkdown(id: string): string {\n  // The `:` of `sha256:…` stays readable and extractable for the model;\n  // everything else is escaped for the path segment.\n  return `![图片](/describe-image/raw/${encodeURIComponent(id).replace(/%3A/gi, ':')})`\n}\n\n/** Build the `[image attachment …]` note text for one reference. */\nexport function attachmentNote(ref: ImageAttachmentRef): string {\n  return `[image attachment ${JSON.stringify(ref)}]`\n}\n\n/**\n * Validate an unknown upload payload and decode its bytes. Pure: no context,\n * no I/O — every rejection reason is spelled in the error message.\n * @param payload - the parsed request body.\n * @param maxBytes - the image byte bound.\n * @returns the validated payload and decoded bytes, or the rejection.\n */\nexport function validateAttachPayload(payload: unknown, maxBytes: number): { payload: AttachPayload; bytes: Buffer } | { error: AttachError } {\n  if (typeof payload !== 'object' || payload === null) {\n    return { error: { code: 'internal', message: 'request body must be a JSON object' } }\n  }\n  const record = payload as Record<string, unknown>\n  const { data, mediaType, name } = record\n  if (typeof data !== 'string' || data.length === 0) {\n    return { error: { code: 'rejected', message: 'image data must be a non-empty base64 string' } }\n  }\n  if (!isImageMimeType(mediaType)) {\n    return { error: { code: 'rejected', message: 'mediaType must be one of image/png, image/jpeg, image/gif, image/webp' } }\n  }\n  if (name !== undefined && (typeof name !== 'string' || name.length === 0)) {\n    return { error: { code: 'rejected', message: 'name must be a non-empty string when present' } }\n  }\n  const bytes = decodeBase64(data)\n  if (bytes === undefined) {\n    return { error: { code: 'rejected', message: 'image data is not valid base64' } }\n  }\n  if (bytes.length === 0) {\n    return { error: { code: 'rejected', message: 'image data is empty' } }\n  }\n  if (bytes.length > maxBytes) {\n    return { error: { code: 'rejected', message: `image is ${bytes.length} bytes, above the ${maxBytes}-byte bound` } }\n  }\n  if (sniffMimeType(bytes) !== mediaType) {\n    return { error: { code: 'rejected', message: `bytes do not match the declared ${mediaType} type` } }\n  }\n  return { payload: { data, mediaType, name }, bytes }\n}\n\n/**\n * Validate and persist one upload. The declared media type is checked against\n * magic bytes before any store write; the store's own validation runs before\n * the reference is published.\n * @param ctx - registrant context carrying the optional attachment service.\n * @param maxBytes - the image byte bound.\n * @param payload - the parsed request body.\n * @returns the stored reference and its note text, or a structured rejection.\n */\nexport async function handleAttach(ctx: Context, maxBytes: number, payload: unknown): Promise<AttachOutcome> {\n  const validated = validateAttachPayload(payload, maxBytes)\n  if ('error' in validated) return { ok: false, error: validated.error }\n  const attachments = ctx.get('attachments')\n  if (attachments === undefined) {\n    return { ok: false, error: { code: 'internal', message: 'the attachment service is not mounted; the route cannot store images' } }\n  }\n  try {\n    const ref = await attachments.saveImage({\n      data: validated.bytes,\n      mediaType: validated.payload.mediaType,\n      ...validated.payload.name === undefined ? {} : { name: validated.payload.name },\n    })\n    registerAttachmentRef(ref)\n    return { ok: true, ref, note: attachmentNote(ref), markdown: attachmentMarkdown(ref.attachmentId) }\n  } catch (error) {\n    return { ok: false, error: { code: 'internal', message: `attachment store rejected the image: ${(error as Error).message ?? String(error)}` } }\n  }\n}\n\n/** Read a JSON request body up to a byte cap; null when unparseable or oversized. */\nasync function readJsonBody(req: IncomingMessage, cap: number): Promise<unknown> {\n  const chunks: Buffer[] = []\n  let total = 0\n  for await (const chunk of req) {\n    const buffer = chunk as Buffer\n    chunks.push(buffer)\n    total += buffer.length\n    if (total > cap) return null\n  }\n  const text = Buffer.concat(chunks).toString('utf8')\n  if (text === '') return null\n  try {\n    return JSON.parse(text) as unknown\n  } catch {\n    return null\n  }\n}\n\n/** Write one JSON envelope response. */\nfunction json(res: ServerResponse, envelope: unknown, status = 200): void {\n  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' })\n  res.end(JSON.stringify(envelope))\n}\n\n/**\n * Serve one stored image by its bare attachment id (the GET half of the\n * prefix route). Unknown ids and store failures answer 404; the media type\n * comes from the registered reference, never from the URL.\n * @param ctx - registrant context carrying the optional attachment service.\n * @param req - the incoming GET request.\n * @param res - the outgoing response.\n */\nasync function serveRawImage(ctx: Context, req: IncomingMessage, res: ServerResponse): Promise<void> {\n  const match = /^\\/describe-image\\/raw\\/([^/]+)$/.exec(new URL(req.url ?? '/', 'http://x').pathname)\n  if (match === null) {\n    res.writeHead(404)\n    res.end()\n    return\n  }\n  const id = decodeURIComponent(match[1])\n  const ref = attachmentRefById(id)\n  if (ref === undefined) {\n    res.writeHead(404)\n    res.end()\n    return\n  }\n  const attachments = ctx.get('attachments')\n  if (attachments === undefined) {\n    res.writeHead(404)\n    res.end()\n    return\n  }\n  try {\n    const stored = await attachments.readImage(ref)\n    res.writeHead(200, { 'content-type': ref.mediaType, 'content-length': String(stored.data.byteLength), 'cache-control': 'private, max-age=3600' })\n    res.end(Buffer.from(stored.data))\n  } catch {\n    res.writeHead(404)\n    res.end()\n  }\n}\n\n/**\n * Register the /describe-image/attach POST route on the shared webserver. The\n * byte bound is read per request so the Settings card's maxBytes change lands\n * immediately; the attachment service is resolved per call.\n * @param ctx - registrant context; webServer is required.\n * @param readMaxBytes - per-request byte-bound reader (defaults to the constant).\n */\nexport function registerAttachRoute(ctx: Context, readMaxBytes: () => number = () => DEFAULT_MAX_BYTES): void {\n  const webserver = ctx.get('webServer')\n  if (webserver === undefined) return\n  webserver.register({\n    kind: 'prefix',\n    path: '/describe-image',\n    handler: async (req: IncomingMessage, res: ServerResponse): Promise<void> => {\n      // GET /describe-image/raw/<id>: serve the stored bytes so the\n      // markdown image reference inserted into the draft renders. The id is\n      // content-addressed and loopback-only, so a bare read carries no\n      // secrets; the store's digest verification still runs.\n      if (req.method === 'GET') {\n        await serveRawImage(ctx, req, res)\n        return\n      }\n      if (req.method !== 'POST') {\n        json(res, { ok: false, error: METHOD_NOT_ALLOWED }, 405)\n        return\n      }\n      const body = await readJsonBody(req, MAX_ATTACH_BODY_BYTES)\n      if (body === null) {\n        json(res, { ok: false, error: { code: 'internal', message: 'request body must be JSON within 16 MiB' } }, 400)\n        return\n      }\n      const outcome = await handleAttach(ctx, readMaxBytes(), body)\n      if (outcome.ok) {\n        json(res, { ok: true, value: { note: outcome.note, markdown: outcome.markdown, ref: outcome.ref } })\n        return\n      }\n      json(res, { ok: false, error: outcome.error }, outcome.error.code === 'rejected' ? 422 : 500)\n    },\n  })\n}\n"
    },
    {
      "path": "packages/dsh-tool-describe-image/src/index.ts",
      "content": "/**\n * Model-facing image understanding for text-only models. Each call loads one image — a local file\n * path or an http(s) URL — and asks a vision-language model at an OpenAI-compatible endpoint to\n * describe it; only the returned text crosses into the conversation, so the image never enters the\n * session log. The API key resolves per call (inline config value, then the credential seam, then\n * the launch environment), and the HTTP client refuses redirects so a bearer credential can never\n * be forwarded off the configured endpoint.\n *\n * Ported from deepseek-harness packages/vision/tool-describe-image (mirrored at\n * whitelonng/dsh-plugin-describe-image). Family adaptation: the plugin may be mounted without\n * configuration (the dsh-web-ui-all aggregate does this), so endpoint/model validation happens per\n * call — or eagerly at load when a composition entry actually configures it. The \"Image\n * understanding\" settings section can fill the fields live from Settings → 插件配置.\n * @module @linxin666/dsh-tool-describe-image\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\nimport { installSettingsSection } from '@deepseek-ai/dsh-settings'\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { GenericCallView } from '@deepseek-ai/dsh-tools'\nimport { registerAttachRoute } from './attach-routes.ts'\nimport { DEFAULT_MAX_BYTES } from './media.ts'\nimport { Config, DESCRIBE_IMAGE_SETTINGS_NAMESPACE, resolveApiKey, resolveConfig, type ResolvedConfig } from './config-resolve.ts'\nimport { callVision, createVisionCache, loadImage } from './vision-client.ts'\n\nexport const name = 'describe-image'\nexport const inject = ['tools', 'webServer']\n\n// Public surface re-exported unchanged from the split modules. Config and its\n// schema const travel together from config-resolve; the settings namespace the\n// Plugins card uses comes from the same module.\n\nexport { DEFAULT_MAX_BYTES, sniffMimeType } from './media.ts'\nexport type { ImageMimeType } from './media.ts'\nexport {\n  API_STYLES,\n  Config,\n  DEFAULT_API_KEY_ENV,\n  DEFAULT_API_STYLE,\n  DEFAULT_MAX_OUTPUT_TOKENS,\n  DEFAULT_PROMPT,\n  DEFAULT_TIMEOUT_MS,\n  DESCRIBE_IMAGE_SETTINGS_NAMESPACE,\n  resolveApiKey,\n  resolveConfig,\n} from './config-resolve.ts'\nexport type { ApiStyle, ResolvedConfig } from './config-resolve.ts'\nexport {\n  callVision,\n  createVisionCache,\n  DEFAULT_CACHE_MAX_ENTRIES,\n  DEFAULT_CACHE_TTL_MS,\n  extractChatCompletionsContent,\n  extractResponsesContent,\n  loadImage,\n  parseImageAttachmentRef,\n  readAttachment,\n  readBoundedBody,\n  readBoundedText,\n  semanticRequestKey,\n} from './vision-client.ts'\nexport type { LoadedImage, VisionCache } from './vision-client.ts'\n\nconst DESCRIPTION_HEAD =\n  'Inspect one image — a local absolute path, an http(s) URL, or the JSON of an image attachment '\n  + 'note — and return the text the user needs. Use when the user references an image file or URL, '\n  + 'or when a task needs OCR, chart or diagram reading, screenshot or UI analysis, translation of '\n  + 'image text, or photo understanding. '\n  + 'Always pass an explicit `prompt` with a precise instruction — e.g. \"transcribe all text\", '\n  + '\"extract the table as CSV\", \"diagnose the UI layout problems\", \"translate the text into '\n  + 'Chinese\" — instead of leaving it to the default description: a targeted instruction produces '\n  + 'a much more useful answer. '\n\n/** The describe_image call’s validated arguments. */\nexport interface DescribeImageArgs {\n  image: string\n  prompt?: string\n}\n\n/**\n * Pure call view: a generic read card, with a file location for local paths.\n * @param args - the validated call arguments.\n * @returns the pending-state card for one describe_image call.\n */\nexport function describeImageCallView(args: DescribeImageArgs): GenericCallView {\n  return {\n    card: 'generic',\n    title: 'Describe image',\n    kind: 'read',\n    rawInput: args,\n    .../^https?:\\/\\//i.test(args.image) ? {} : { locations: [{ path: args.image }] },\n  }\n}\n\n/**\n * Register the `describe_image` tool on `ctx.tools`. The image never enters the conversation: the\n * tool returns only the vision model’s text answer. The `describe-image` settings section layers\n * over the composition entry and is re-resolved per call, so the Settings → 插件配置 card's changes\n * reach the very next invocation. Repeat calls for the same image and prompt reuse a short-lived\n * semantic cache so the endpoint is not called twice in quick succession.\n *\n * Family adaptation: the aggregate mounts this plugin without configuration, so endpoint/model\n * validation is lazy — an empty composition entry loads fine and the first call fails with a clear\n * \"unconfigured\" message; a non-empty entry is still validated eagerly at load and fails loud.\n * @param ctx - registrant context carrying the tool registry.\n * @param config - deployment configuration.\n */\nexport function apply(ctx: Context, config: Config = {}): void {\n  // The loader fills schema defaults before apply, so an unconfigured entry\n  // still arrives with default fields set. Only a config that actually names\n  // the endpoint/model is validated eagerly — the family aggregate mounts\n  // without configuration and must load silently.\n  if (config.baseURL !== undefined || config.model !== undefined) {\n    resolveConfig(config)\n  }\n  let current: () => Config = () => config\n  installSettingsSection(ctx, DESCRIBE_IMAGE_SETTINGS_NAMESPACE, Config, config, {\n    setSource: (source) => {\n      current = source\n    },\n    onChange: () => {},\n    validate: (value) => {\n      if (value.baseURL !== undefined || value.model !== undefined) resolveConfig(value)\n    },\n  })\n  const spec = (): ResolvedConfig => resolveConfig(current())\n  // Short-lived semantic cache scoped to this mount: identical image + prompt\n  // within the TTL reuse the prior answer instead of a second fetch.\n  const visionCache = createVisionCache()\n  // The webserver is optional (the loader-composition tests boot without one):\n  // the attach route registers only when the service is actually mounted.\n  registerAttachRoute(ctx, () => current().maxBytes ?? DEFAULT_MAX_BYTES)\n  ctx.tools.register(defineTool({\n    name: 'describe_image',\n    description: DESCRIPTION_HEAD\n      + 'The image may be a local path, an http(s) URL, the JSON object from an `[image attachment …]` '\n      + \"note, or — the common case when the user used this plugin's input-box image button — a \"\n      + 'short markdown image reference like `![图片](/describe-image/raw/sha256:abc…)` pasted into '\n      + 'the conversation. In the markdown form, take the attachment id from the URL and pass that id '\n      + 'as the `image` value (never the whole markdown, and never a made-up path); the tool resolves '\n      + 'the id to the stored image. The image itself never enters the conversation — only the '\n      + 'returned text is shown to you.',\n    parameters: {\n      image: {\n        type: 'string',\n        required: true,\n        description: 'Absolute path to a local image file, an http(s) URL of the image, the JSON object from an [image attachment …] note, or the bare attachment id (e.g. sha256:abc…) taken from the markdown image reference ![图片](/describe-image/raw/<id>) that the plugin\\'s input-box image button pasted into the conversation.',\n      },\n      prompt: {\n        type: 'string',\n        description: 'Your precise instruction for the vision model about this image (e.g. \"transcribe all text\", \"extract the table as CSV\", \"diagnose the UI problems\", \"translate the text\"). Prefer a targeted prompt over the generic default description.',\n      },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          text: { type: 'string', required: true },\n          model: { type: 'string', required: true },\n          image: { type: 'string', required: true },\n          mimeType: { type: 'string', required: true, enum: ['image/png', 'image/jpeg', 'image/gif', 'image/webp'] },\n          bytes: { type: 'integer', required: true },\n        },\n      },\n      render: (_args, value) => [{ type: 'text', text: value.text }],\n    },\n    async execute(args, exec) {\n      const active = spec()\n      const apiKey = await resolveApiKey(ctx, active)\n      const image = await loadImage(ctx, args.image, exec.signal, active.maxBytes)\n      const text = await callVision(active, apiKey, args.prompt ?? active.defaultPrompt, image, exec.signal, visionCache)\n      return { text, model: active.model, image: args.image, mimeType: image.mimeType, bytes: image.bytes.length }\n    },\n    presentCall: describeImageCallView,\n  }))\n}"
    },
    {
      "path": "packages/dsh-tool-describe-image/src/vision-client.ts",
      "content": "/**\n * Vision HTTP client for the describe-image tool: loads one image (local path,\n * http(s) URL, or a stored attachment reference), builds the endpoint request that\n * matches the configured protocol style (chat-completions or responses), and reads\n * back the single text answer — with a short-lifetime, capacity-capped semantic\n * cache so repeat calls for the same image and prompt avoid a second round trip.\n * Response bodies and error excerpts are capped before any bytes are trusted.\n * @module @linxin666/dsh-tool-describe-image/vision\n */\n\nimport { readFile, stat } from 'node:fs/promises'\nimport type { Context } from '@deepseek-ai/cordis'\nimport type { ImageAttachmentRef } from '@deepseek-ai/dsh-attachment'\nimport { attachmentRefById } from './attach-routes.ts'\nimport { DEFAULT_MAX_BYTES, isImageMimeType, sniffMimeType, type ImageMimeType } from './media.ts'\nimport type { ApiStyle, ResolvedConfig } from './config-resolve.ts'\n\n/** One loaded image: its bytes and the sniffed media type. */\nexport interface LoadedImage {\n  bytes: Buffer\n  mimeType: ImageMimeType\n}\n\n/** Error text shown when a model-supplied attachment reference does not validate. */\nconst ATTACHMENT_REF_GUIDANCE =\n  'describe-image: image is not a valid attachment reference; copy the exact JSON from the [image attachment …] note'\n\n/** Promise rejection helper shared by both response-shape extractors. */\nfunction unexpectedShape(): never {\n  throw new Error('describe-image: vision endpoint returned an unexpected response shape')\n}\n\n/** Narrow an unknown value to a plain, non-array object, or undefined. */\nfunction asRecord(value: unknown): Record<string, unknown> | undefined {\n  if (typeof value !== 'object' || value === null || Array.isArray(value)) return undefined\n  return value as Record<string, unknown>\n}\n\n/** Whether a record field holds a positive safe integer. */\nfunction isPositiveSafeInteger(value: unknown): value is number {\n  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0\n}\n\n/** A non-empty string from a record under `key`, else undefined. */\nfunction nonEmptyString(record: Record<string, unknown>, key: string): string | undefined {\n  const value = record[key]\n  return typeof value === 'string' && value.length > 0 ? value : undefined\n}\n\n/** Whether `error` carries the attachment store not-found marker. */\nfunction isAttachmentNotFound(error: unknown): boolean {\n  return asRecord(error)?.['code'] === 'ATTACHMENT_NOT_FOUND'\n}\n\n/**\n * Validate and narrow a model-supplied attachment reference into its typed storage\n * form. Every field is re-checked (the schema is authoritative, not a cast), and a\n * misshaped value fails with the copy-verbatim guidance.\n * @param raw - the JSON the model copied from an `[image attachment …]` note.\n * @returns the narrowed, typed reference.\n */\nexport function parseImageAttachmentRef(raw: string): ImageAttachmentRef {\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(raw)\n  } catch {\n    throw new Error(ATTACHMENT_REF_GUIDANCE)\n  }\n  const record = asRecord(parsed)\n  if (record === undefined) throw new Error(ATTACHMENT_REF_GUIDANCE)\n  const attachmentId = nonEmptyString(record, 'attachmentId')\n  const mediaType = record['mediaType']\n  const bytes = record['bytes']\n  const width = record['width']\n  const height = record['height']\n  const name = record['name']\n  if (attachmentId === undefined\n    || !isImageMimeType(mediaType)\n    || !isPositiveSafeInteger(bytes)\n    || !isPositiveSafeInteger(width)\n    || !isPositiveSafeInteger(height)\n    || (name !== undefined && typeof name !== 'string')) {\n    throw new Error(ATTACHMENT_REF_GUIDANCE)\n  }\n  const ref: ImageAttachmentRef = {\n    attachmentId: attachmentId as ImageAttachmentRef['attachmentId'],\n    mediaType,\n    bytes,\n    width,\n    height,\n    ...name === undefined ? {} : { name },\n  }\n  return ref\n}\n\n/**\n * Validate a model-supplied attachment reference and read its verified bytes.\n * @param ctx - registrant context carrying the optional attachment service.\n * @param raw - the raw JSON the model copied from an `[image attachment …]` note.\n * @param signal - caller cancellation.\n * @returns the verified stored bytes.\n */\nexport async function readAttachment(ctx: Context, raw: string, signal: AbortSignal): Promise<Buffer> {\n  const attachments = ctx.get('attachments')\n  if (attachments === undefined) {\n    throw new Error('describe-image: no attachment service is mounted; pass a file path or URL instead')\n  }\n  const ref = parseImageAttachmentRef(raw)\n  try {\n    const stored = await attachments.readImage(ref, signal)\n    return Buffer.from(stored.data)\n  } catch (error) {\n    if (isAttachmentNotFound(error)) {\n      throw new Error(`describe-image: attachment ${JSON.stringify(ref.attachmentId)} is no longer available`)\n    }\n    throw error\n  }\n}\n\n/** Sniff the media type and reject empty or unsupported inputs. */\nfunction toImage(bytes: Buffer, source: string): LoadedImage {\n  if (bytes.length === 0) throw new Error(`describe-image: image is empty: ${source}`)\n  const mimeType = sniffMimeType(bytes)\n  if (mimeType === undefined) {\n    throw new Error(`describe-image: unsupported image type (expected PNG, JPEG, GIF, or WebP): ${source}`)\n  }\n  return { bytes, mimeType }\n}\n\n/**\n * Load one image from a local absolute path, an http(s) URL, or a durable attachment reference\n * (the JSON an `[image attachment …]` note carries), enforcing the byte bound before any bytes\n * reach the vision model. Non-http(s) URL schemes are rejected.\n * @param ctx - registrant context; supplies the optional attachment service.\n * @param input - the model-supplied image reference.\n * @param signal - caller cancellation.\n * @param maxBytes - image byte bound.\n * @returns the loaded bytes and sniffed media type.\n */\nexport async function loadImage(ctx: Context, input: string, signal: AbortSignal, maxBytes: number): Promise<LoadedImage> {\n  const trimmed = input.trim()\n  if (trimmed.length === 0) throw new Error('describe-image: image must be a non-empty path, URL, or attachment reference')\n  if (/^[a-z][a-z0-9+.-]*:\\/\\//i.test(trimmed) && !/^https?:\\/\\//i.test(trimmed)) {\n    throw new Error('describe-image: only http(s) URLs, local file paths, and attachment references are supported')\n  }\n  if (trimmed.startsWith('{')) {\n    const bytes = await readAttachment(ctx, trimmed, signal)\n    if (bytes.length > maxBytes) {\n      throw new Error(`describe-image: image is ${bytes.length} bytes, above the ${maxBytes}-byte bound`)\n    }\n    return toImage(bytes, trimmed.slice(0, 96))\n  }\n  if (/^https?:\\/\\//i.test(trimmed)) {\n    const response = await fetch(trimmed, { signal, redirect: 'error' })\n    if (!response.ok) {\n      throw new Error(`describe-image: image fetch returned HTTP ${response.status}`)\n    }\n    const declared = Number(response.headers.get('content-length'))\n    if (Number.isSafeInteger(declared) && declared > maxBytes) {\n      throw new Error(`describe-image: image is ${declared} bytes, above the ${maxBytes}-byte bound`)\n    }\n    const bytes = await readBoundedBody(response, maxBytes)\n    return toImage(bytes, trimmed)\n  }\n  // A bare attachment id — the `sha256:…` string text models tend to copy out of\n  // an `[image attachment …]` note instead of the whole JSON. Resolve it through\n  // the attach-route registry (the store's digest verification still runs).\n  const registered = attachmentRefById(trimmed)\n  if (registered !== undefined) {\n    const bytes = await readAttachment(ctx, JSON.stringify(registered), signal)\n    if (bytes.length > maxBytes) {\n      throw new Error(`describe-image: image is ${bytes.length} bytes, above the ${maxBytes}-byte bound`)\n    }\n    return toImage(bytes, trimmed)\n  }\n  const info = await stat(trimmed, { bigint: false })\n  if (!info.isFile()) throw new Error(`describe-image: image path is not a file: ${trimmed}`)\n  if (info.size > maxBytes) {\n    throw new Error(`describe-image: image is ${info.size} bytes, above the ${maxBytes}-byte bound`)\n  }\n  const bytes = await readFile(trimmed, { signal })\n  return toImage(bytes, trimmed)\n}\n\n/**\n * Read a response body up to a byte cap, rejecting the whole response beyond it.\n * @param response - the response to drain.\n * @param cap - the byte bound.\n * @returns the accumulated body bytes.\n */\nexport async function readBoundedBody(response: Response, cap: number): Promise<Buffer> {\n  if (response.body === null) return Buffer.alloc(0)\n  const reader = response.body.getReader()\n  const chunks: Buffer[] = []\n  let total = 0\n  try {\n    for (;;) {\n      const { done, value } = await reader.read()\n      if (done) break\n      const chunk = Buffer.from(value)\n      total += chunk.length\n      if (total > cap) throw new Error(`describe-image: response exceeds the ${cap}-byte bound`)\n      chunks.push(chunk)\n    }\n  } finally {\n    reader.releaseLock()\n  }\n  return Buffer.concat(chunks)\n}\n\n/**\n * Read a response body as text, truncated to a character cap (error excerpts only).\n * @param response - the response to drain.\n * @param cap - the character cap.\n * @returns the decoded text, never longer than `cap` characters.\n */\nexport async function readBoundedText(response: Response, cap: number): Promise<string> {\n  if (response.body === null) return ''\n  const reader = response.body.getReader()\n  const decoder = new TextDecoder()\n  let text = ''\n  try {\n    for (;;) {\n      const { done, value } = await reader.read()\n      if (done) break\n      text += decoder.decode(value, { stream: true })\n      if (text.length > cap) return text.slice(0, cap)\n    }\n    text += decoder.decode()\n  } finally {\n    reader.releaseLock()\n  }\n  return text.length > cap ? text.slice(0, cap) : text\n}\n\n/** Extract the single text answer from an OpenAI-compatible chat-completions payload. */\nexport function extractChatCompletionsContent(payload: unknown): string {\n  const root = asRecord(payload)\n  const choices = root?.choices\n  if (root === undefined || !Array.isArray(choices) || choices.length === 0) unexpectedShape()\n  const message = asRecord(asRecord(choices[0])?.message)\n  const content = message?.['content']\n  if (typeof content !== 'string' || content.trim().length === 0) {\n    throw new Error('describe-image: vision endpoint returned no text content')\n  }\n  return content\n}\n\n/** Extract the text answer from an OpenAI Responses payload: every `output_text` part of assistant messages. */\nexport function extractResponsesContent(payload: unknown): string {\n  const root = asRecord(payload)\n  const output = root?.output\n  if (root === undefined || !Array.isArray(output)) unexpectedShape()\n  const parts: string[] = []\n  for (const item of output) {\n    const itemRecord = asRecord(item)\n    if (itemRecord === undefined) continue\n    const { type, role, content } = itemRecord\n    if (type !== 'message' || role !== 'assistant' || !Array.isArray(content)) continue\n    for (const part of content) {\n      const block = asRecord(part)\n      if (block === undefined) continue\n      if (block.type === 'output_text' && typeof block.text === 'string' && block.text.trim().length > 0) {\n        parts.push(block.text)\n      }\n    }\n  }\n  const text = parts.join('\\n')\n  if (text.trim().length === 0) {\n    throw new Error('describe-image: vision endpoint returned no text content')\n  }\n  return text\n}\n\n/** Build the request the configured style sends: its path and JSON body. */\nexport function buildVisionRequest(spec: ResolvedConfig, prompt: string, image: LoadedImage): { path: string; body: string } {\n  const dataUrl = `data:${image.mimeType};base64,${image.bytes.toString('base64')}`\n  if (spec.apiStyle === 'responses') {\n    return {\n      path: `${spec.baseURL}/responses`,\n      body: JSON.stringify({\n        model: spec.model,\n        max_output_tokens: spec.maxOutputTokens,\n        input: [{\n          role: 'user',\n          content: [\n            { type: 'input_text', text: prompt },\n            { type: 'input_image', image_url: dataUrl },\n          ],\n        }],\n      }),\n    }\n  }\n  return {\n    path: `${spec.baseURL}/chat/completions`,\n    body: JSON.stringify({\n      model: spec.model,\n      max_tokens: spec.maxOutputTokens,\n      messages: [{\n        role: 'user',\n        content: [\n          { type: 'text', text: prompt },\n          { type: 'image_url', image_url: { url: dataUrl } },\n        ],\n      }],\n    }),\n  }\n}\n\n/** Default semantic-cache lifetime for a successful vision answer, in milliseconds. */\nexport const DEFAULT_CACHE_TTL_MS = 10_000\n/** Default upper bound on cached vision answers. */\nexport const DEFAULT_CACHE_MAX_ENTRIES = 32\n\n/** A bounded, TTL-expiring cache of successful vision answers. */\nexport interface VisionCache {\n  /** Look up a cached answer, honoring the TTL. */\n  get(key: string): string | undefined\n  /** Store an answer with a fresh TTL, evicting expired and then oldest entries. */\n  set(key: string, text: string): void\n  /** Number of live cached answers. */\n  readonly size: number\n  /** Running cache hits, for observability and tests. */\n  readonly hits: number\n  /** Running cache misses, for observability and tests. */\n  readonly misses: number\n  /** Drop every entry. */\n  clear(): void\n}\n\n/** Create a TTL-expiring, capacity-capped vision answer cache. */\nexport function createVisionCache(options?: { ttlMs?: number; maxEntries?: number }): VisionCache {\n  const ttlMs = options?.ttlMs ?? DEFAULT_CACHE_TTL_MS\n  const maxEntries = Math.max(1, options?.maxEntries ?? DEFAULT_CACHE_MAX_ENTRIES)\n  const entries = new Map<string, { text: string; expiresAt: number }>()\n  let hits = 0\n  let misses = 0\n  return {\n    get(key) {\n      const entry = entries.get(key)\n      if (entry === undefined) { misses += 1; return undefined }\n      if (entry.expiresAt <= Date.now()) { entries.delete(key); misses += 1; return undefined }\n      hits += 1\n      return entry.text\n    },\n    set(key, text) {\n      const now = Date.now()\n      for (const [k, entry] of entries) if (entry.expiresAt <= now) entries.delete(k)\n      entries.set(key, { text, expiresAt: now + ttlMs })\n      while (entries.size > maxEntries) {\n        const oldest = entries.keys().next().value\n        if (oldest === undefined) break\n        entries.delete(oldest)\n      }\n    },\n    get size() { return entries.size },\n    get hits() { return hits },\n    get misses() { return misses },\n    clear() { entries.clear() },\n  }\n}\n\n/** The semantic identity of one vision request: endpoint fields plus the same image bytes and prompt. */\nexport function semanticRequestKey(spec: ResolvedConfig, prompt: string, image: LoadedImage): string {\n  return JSON.stringify([\n    spec.baseURL, spec.model, spec.maxOutputTokens, spec.apiStyle,\n    image.bytes.toString('base64'), image.mimeType, prompt,\n  ])\n}\n\n/** Call the configured vision endpoint and return its text answer, with short-lifetime caching for repeats. */\nexport async function callVision(\n  spec: ResolvedConfig,\n  apiKey: string,\n  prompt: string,\n  image: LoadedImage,\n  signal: AbortSignal,\n  cache?: VisionCache,\n): Promise<string> {\n  if (cache !== undefined) {\n    const cached = cache.get(semanticRequestKey(spec, prompt, image))\n    if (cached !== undefined) return cached\n  }\n  const { path, body } = buildVisionRequest(spec, prompt, image)\n  const response = await fetch(path, {\n    method: 'POST',\n    headers: { 'content-type': 'application/json', authorization: `Bearer ${apiKey}` },\n    body,\n    redirect: 'error',\n    signal: AbortSignal.any([signal, AbortSignal.timeout(spec.timeoutMs)]),\n  })\n  if (!response.ok) {\n    const excerpt = await readBoundedText(response, 200)\n    throw new Error(`describe-image: vision endpoint returned HTTP ${response.status}: ${excerpt}`)\n  }\n  const payloadBytes = await readBoundedBody(response, spec.maxOutputTokens * 8 + 64 * 1024)\n  let payload: unknown\n  try {\n    payload = JSON.parse(payloadBytes.toString('utf8'))\n  } catch {\n    throw new Error('describe-image: vision endpoint returned invalid JSON')\n  }\n  const text = spec.apiStyle === 'responses' ? extractResponsesContent(payload) : extractChatCompletionsContent(payload)\n  if (cache !== undefined) cache.set(semanticRequestKey(spec, prompt, image), text)\n  return text\n}"
    }
